Object.values(CONTROCORRENTE_MENU).forEach(menu=>{
 menu.courses.forEach((c,i)=>c.dishes.forEach((d,j)=>{const shared=SHARED_DINNER[['antipasti','primi','secondi'][i]][j]; d[2]=new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR'}).format(shared.price);d[1]=d[1].replace(/\([\d, ]+\)[.]?$/, '')+(shared.allergens.length?' ('+shared.allergens.join(', ')+')':'');}));
 menu.daily.forEach((d,i)=>{d[1]=d[1].replace(/\([\d, ]+\)\.?$/, '').trim()+(SHARED_OFFERS[i].allergens.length?' ('+SHARED_OFFERS[i].allergens.join(', ')+')':'');d[2]=new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR'}).format(SHARED_OFFERS[i].price);});
 menu.fixed.forEach((d,i)=>{d[1]=d[1].replace(/\([\d, ]+\)\.?$/, '').trim()+' ('+SHARED_FIXED.dishes[i].allergens.join(', ')+')';});
});

function renderTranslatedMenu() {
  const root = document.querySelector("[data-menu-language]");
  if (!root) return;
  const language = root.dataset.menuLanguage;
  const menu = CONTROCORRENTE_MENU[language];
  root.querySelector("h1").textContent = menu.title;
  root.querySelector(".language-head p").textContent = menu.subtitle;
  const content = root.querySelector(".translated-menu-content");
  [...menu.courses,
    { title: menu.dailyTitle, dishes: menu.daily, daily: true },
    ...(menu.fixed.length ? [{ title: menu.fixedTitle, dishes: menu.fixed, daily: true, note: menu.fixedNote }] : [])
  ].forEach(course => {
    const section = document.createElement("section");
    section.className = course.daily ? "language-course language-daily" : "language-course";
    const heading = document.createElement("h2");
    heading.textContent = course.title;
    section.appendChild(heading);
    course.dishes.forEach(([name, description, price]) => {
      const article = document.createElement("article");
      article.className = "language-dish";
      const title = document.createElement("h3");
      title.textContent = name;
      if (price) {
        const amount = document.createElement("span");
        amount.className = "language-price";
        amount.textContent = price;
        title.appendChild(amount);
      }
      const text = document.createElement("p");
      const refs=description.match(/\(([\d, ]+)\)\.?$/)||description.match(/([\d, ]+)$/);
      text.textContent=refs ? description.slice(0,refs.index).replace(/[ ·]+$/,'').trim() : description;
      if(refs){
        const badges=document.createElement('p');badges.className='allergen-refs';
        refs[1].split(',').map(Number).filter(n=>SHARED_ALLERGEN_SYMBOLS[n]).forEach(number=>{
          const info=SHARED_ALLERGEN_SYMBOLS[number];
          const badge=document.createElement('span');badge.className='allergen-badge';badge.title=info.name;badge.setAttribute('aria-label',String(number).padStart(2,'0')+' · '+info.name);
          const pictogram=document.createElement('span');pictogram.className='allergen-pictogram';
          const image=document.createElement('img');image.className='icon';image.src='icons/'+info.icon+'.svg';image.alt='';image.setAttribute('aria-hidden','true');pictogram.append(image);
          const label=document.createElement('span');label.className='allergen-number';label.textContent=String(number).padStart(2,'0');
          badge.append(pictogram,label);badges.append(badge);
        });article.append(badges);
      }
      article.prepend(title, text);
      section.appendChild(article);
    });
    if (course.note) {
      const note = document.createElement("p");
      note.textContent = course.note;
      section.appendChild(note);
    }
    content.appendChild(section);
  });
  root.querySelector(".language-note").textContent = menu.note;
}

document.addEventListener("DOMContentLoaded", renderTranslatedMenu);


